function nearestUsecase(x, z){
  let best=null;
  let bestDistance=USECASE_SNAP_M;
  for(const usecase of markerCases){
    const distance=Math.hypot(usecase.x-x, usecase.z-z);
    if(distance<=bestDistance){
      best=usecase;
      bestDistance=distance;
    }
  }
  return best;
}
